CREATE TABLE IF NOT EXISTS audit_log (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor VARCHAR(80) NOT NULL, action VARCHAR(160) NOT NULL, resource VARCHAR(200) NOT NULL, status_code INT NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX(created_at));
CREATE TABLE IF NOT EXISTS inspections (id BIGINT AUTO_INCREMENT PRIMARY KEY, bridge_id INT NOT NULL, title VARCHAR(160) NOT NULL, notes TEXT NOT NULL, responsible VARCHAR(120) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'open', inspected_at DATETIME(3) NOT NULL, next_inspection DATE NULL, created_by VARCHAR(80) NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(bridge_id) REFERENCES bridges(id));
CREATE TABLE IF NOT EXISTS inspection_photos (id BIGINT AUTO_INCREMENT PRIMARY KEY, inspection_id BIGINT NOT NULL, mime VARCHAR(30) NOT NULL, image MEDIUMBLOB NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(inspection_id) REFERENCES inspections(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS sensor_baselines (id BIGINT AUTO_INCREMENT PRIMARY KEY, device_id VARCHAR(40) NOT NULL, label VARCHAR(100) NOT NULL, from_at DATETIME(3) NOT NULL, to_at DATETIME(3) NOT NULL, sample_count INT NOT NULL, mean_rms DOUBLE NOT NULL, max_rms DOUBLE NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(device_id) REFERENCES devices(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS device_credentials (device_id VARCHAR(40) PRIMARY KEY, token_hash CHAR(64) NOT NULL, rotated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(device_id) REFERENCES devices(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS remote_samples (id BIGINT AUTO_INCREMENT PRIMARY KEY, device_id VARCHAR(40) NOT NULL, boot_id VARCHAR(64) NOT NULL, sequence_no BIGINT UNSIGNED NOT NULL, measured_at DATETIME(3) NOT NULL, received_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), x DOUBLE NOT NULL, y DOUBLE NOT NULL, z DOUBLE NOT NULL, temperature DOUBLE NULL, tilt_x DOUBLE NULL, tilt_y DOUBLE NULL, disposition VARCHAR(16) NOT NULL DEFAULT 'pending', UNIQUE(device_id,boot_id,sequence_no), INDEX(device_id,measured_at), FOREIGN KEY(device_id) REFERENCES devices(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS escalation_config (id INT PRIMARY KEY, config JSON NOT NULL);
INSERT IGNORE INTO escalation_config VALUES (1,'{"enabled":false,"recipient":"","delayMinutes":10}');
CREATE TABLE IF NOT EXISTS alert_escalations (alert_id BIGINT PRIMARY KEY, recipient VARCHAR(254) NOT NULL, state VARCHAR(20) NOT NULL DEFAULT 'queued', attempts INT NOT NULL DEFAULT 0, detail VARCHAR(255), next_attempt_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), sent_at DATETIME(3) NULL, FOREIGN KEY(alert_id) REFERENCES alerts(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS alert_notes (id BIGINT AUTO_INCREMENT PRIMARY KEY, alert_id BIGINT NOT NULL, actor VARCHAR(80) NOT NULL, note VARCHAR(1000) NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(alert_id) REFERENCES alerts(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS push_subscriptions (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, endpoint_hash CHAR(64) UNIQUE NOT NULL, subscription JSON NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(user_id) REFERENCES app_users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS push_deliveries (id BIGINT AUTO_INCREMENT PRIMARY KEY, alert_id BIGINT NOT NULL, subscription_id BIGINT NOT NULL, state VARCHAR(20) NOT NULL DEFAULT 'queued', attempts INT NOT NULL DEFAULT 0, next_attempt_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE(alert_id,subscription_id), FOREIGN KEY(alert_id) REFERENCES alerts(id) ON DELETE CASCADE, FOREIGN KEY(subscription_id) REFERENCES push_subscriptions(id) ON DELETE CASCADE);
